import React from 'react';
import './notice_scss/notice_write.scss';
import NoticeLeftNavComponent from './NoticeComponent/NoticeLeftNavComponent';
import axios from 'axios';
import { GlobalContext } from '../../../context/GlobalContext';

export default function NoticeWriteFormPageComponent () {

    const { isAdmin } = React.useContext(GlobalContext);

    const [state, setState] = React.useState({
        작성자: isAdmin.adminId,
        제목: '',
        내용: ''
    });

    // 현재 로그인한 관리자 아이디로 작성자 바인딩
    const onChangeWriter = (e) => {
        setState({ ...state, 작성자: e.target.value });
    };

    // 제목 입력
    const onChangeSubject = (e) => {
        setState({ ...state, 제목: e.target.value });
    };

    // 내용 입력
    const onChangeContents = (e) => {
        setState({ ...state, 내용: e.target.value });
    };

    // 글쓰기 제출
    const onSubmitWrite = async (e) => {
        e.preventDefault();

        const params = new URLSearchParams();
        params.append('userId', state.작성자);
        params.append('subject', state.제목);
        params.append('content', state.내용);

        try {
            const res = await axios.post(
                'https://kimdohui.com/admin/writeAction_react.jsp',
                params.toString(),
                {
                    headers: { 'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8' }
                }
            );

            const data = res.data;

            if(data.result === 1) {
                alert(data.msg);
                window.location.hash = '#/notice';
            } else {
                alert(data.msg || '등록 실패');
            }

        } catch(err) {
            console.error('AXIOS 실패', err);
            alert('서버 요청 중 오류가 발생했습니다.');
        }
    };

    return (
        <div id='noticeWrite' className='noticeWrite'>
            <div className="container">
                <div className="left">
                    <NoticeLeftNavComponent/>
                </div>
                <div className="right">
                    <div className="title">
                        <h2>공지사항</h2>
                    </div>
                    <div className="content">
                        <form onSubmit={onSubmitWrite}>
                            <ul>
                                <li>
                                    <label htmlFor="subject">제목<i>*</i></label>
                                    <input 
                                        onChange={onChangeSubject}
                                        type="text" 
                                        id='subject'
                                        name='subject' 
                                        value={state.제목} 
                                        placeholder='제목을 입력해주세요'
                                        required
                                    />
                                </li>
                                <li>
                                    <label htmlFor="writer">작성자<i>*</i></label>
                                    <input
                                        type="text"
                                        id="writer"
                                        name="writer"
                                        value={state.작성자}
                                        onChange={onChangeWriter}
                                        placeholder='작성자를 입력해주세요'
                                        disabled
                                    />
                                </li>
                                <li>
                                    <label htmlFor="contents">내용<i>*</i></label>
                                    <textarea 
                                        onChange={onChangeContents}
                                        id='contents'
                                        name="contents"  
                                        placeholder='내용을 입력해주세요' 
                                        value={state.내용}
                                        required
                                    ></textarea>
                                </li>
                            </ul> 

                            <div className="button-box">
                                <button type='submit'>등록</button> 
                            </div>
                        </form>
                    </div>
                </div>
            </div>
        </div>
    );
};
