import React from 'react';
import {Link} from 'react-router-dom';
import '../scss/signin.scss';
import axios from 'axios';
import {ConfirmContext} from '../../../context/ConfirmContext';
import {GlobalContext} from '../../../context/GlobalContext';
import {useNavigate}  from 'react-router-dom';
import cryptoJs from 'crypto-js';

export default function AdminLoginComponent () {


    // 라우터 네비게이트 훅 사용 등록
    const navigate = useNavigate();
    const {login, setLogin, signin, setSignin, isAdmin, setAdmin} = React.useContext(GlobalContext);
    const {confirmModalOpen, isConfirmModal} = React.useContext(ConfirmContext);

    // 아이디, 비밀번호 
    const [state, setState] = React.useState({
        adminId: '',
        adminPw: ''
    });
    const {adminId, adminPw} = state;

    // 아이디 입력상자
    const onChangeAdminId=(e)=>{
        setState({
            ...state,
            adminId: e.target.value
        })
    }

    // 비밀번호 입력상자
    const onChangeAdminPw=(e)=>{
        setState({
            ...state,
            adminPw: e.target.value
        })
    }



    // 로그인 구현
    // loginActionReact.jsp
    const onClickLogin=(e)=>{
        e.preventDefault();

        if(adminId===''){
            confirmModalOpen('아이디를 입력해주세요');
        }
        else if(adminPw===''){
            confirmModalOpen('비밀번호를 입력해주세요');
        }
        else {

            axios({
                url:'https://kimdohui.com/admin/loginActionReact.jsp',
                method: 'POST',
                data:{},
                params: {
                    "userId": adminId,
                    "userPw": adminPw
                }
            })
            .then((res)=>{
                
                if(res.status===200){
                    const result = res.data;
                    try {                    
                        if( result === -1 ){
                            confirmModalOpen('관리자가 아닙니다. 관리자 회원가입하세요');
                            setTimeout(function(){
                                window.location.hash = `https://kimdohui.com/admin/signup.jsp`;
                            }, 1000);                                                       
                        }
                        else if( result === 0 ){
                            confirmModalOpen('비밀번호 오류');                        
                        }
                        else{
                            // 로그인 성공
                            const toDay = new Date();
                            toDay.setDate(toDay.getDate()+3); // 로그인 3일후 만료
                            // toDay.setSeconds(toDay.getSeconds()+5); // 테스트용 5초
                            
                            const adminData = {
                                adminId,
                                adminExpires: toDay.getTime()
                            }

                            setAdmin({
                                ...adminData,
                                adminLoginKey: isAdmin.adminLoginKey
                            })
                
                            // 암호화 Encryption
                            let encryption = cryptoJs.AES.encrypt(JSON.stringify(adminData), isAdmin.adminLoginKey).toString();
                            encryption = encryption.replaceAll('==', '');  // == 삭제
                            localStorage.setItem(isAdmin.adminLoginKey, JSON.stringify({value: encryption}));  // 암호화된 로그인정보 localstorage에 저장

                            confirmModalOpen('로그인 되었습니다.');
                            setTimeout(function(){
                                // window.location.hash = '#/main';
                                navigate('/main');
                            }, 1000); 
                        }
                    } catch (error) {
                        console.log( error );
                    }
                }
                
            })
            .catch((err)=>{
                console.log(`AXIOS 실패 ${err} `)
            });  

        }

    }





    return (
        <main id='signIn'>
            <section id="secino1">
                <div className="container">
                    <div className="title">
                        <h2>관리자 로그인</h2>
                    </div>
                    <div className="content">
                        <form autoComplete='off'>
                            <ul>
                                <li>
                                    <input 
                                    onChange={onChangeAdminId}
                                    type="text" 
                                    name='user_id' 
                                    id='userId' 
                                    value={adminId} 
                                    placeholder='아이디를 입력해주세요' 
                                    />
                                </li>
                                <li>
                                    <input 
                                    onChange={onChangeAdminPw}
                                    type="password" 
                                    name='user_pw' 
                                    id='userPw' 
                                    value={adminPw} 
                                    placeholder='비밀번호를 입력해주세요' 
                                    />
                                </li>
                                <li>
                                    <span>
                                        <Link to="https://kimdohui.com/admin/idSearchForm.jsp" target='_blank'>아이디 찾기</Link>
                                        <i>|</i>
                                        <Link to="https://kimdohui.com/admin/pwSearchForm.jsp" target='_blank'>비밀번호 찾기</Link>
                                    </span></li>
                                <li><button onClick={onClickLogin}>로그인</button></li>
                                <li><Link to="https://kimdohui.com/admin/signup.jsp" target='_blank'>회원가입</Link></li>
                            </ul>
                        </form>
                    </div>
                </div>
            </section>
        </main>
    );
};