import React from 'react';
import './notice_scss/notice_write.scss';
import NoticeLeftNavComponent from './NoticeComponent/NoticeLeftNavComponent';
import { GlobalContext } from '../../../context/GlobalContext';
import { useLocation } from 'react-router-dom';
import axios from 'axios';

export default function NoticeUpdateFormPageComponent() {

    const {isAdmin, setAdmin} = React.useContext(GlobalContext);

    const location = useLocation();
    const { 번호, 제목, 작성자, 내용 } = location.state;

    // 상태 변수
    const [state, setState] = React.useState({
        번호: '',
        제목: '',
        작성자:'',
        내용: ''
    });

    // location.state로 받은 데이터로 초기화
    React.useEffect(() => {
        setState({
            번호,
            제목,
            작성자: isAdmin.adminId,  // 현재 로그인한 관리자 아이디로 작성자 바꿈
            내용
        });
    }, [번호, 제목, 작성자, 내용]);

    // 제목 입력 처리
    const onChangeSubject = (e) => {
        setState({
            ...state,
            제목: e.target.value
        });
    }

    // 현재 로그인한 관리자 아이디로 작성자 바인딩
    const onChangeWriter=e=>{
        setState({
            ...state,
            작성자: e.target.value
        });
    }

    // 내용 입력 처리
    const onChangeContents = (e) => {
        setState({
            ...state,
            내용: e.target.value
        });
    }

    // 저장 버튼 클릭
    const onClickSave = async (e) => {
        e.preventDefault();

        try {

            const params = new URLSearchParams();
            params.append("bbsId", state.번호);
            params.append("subject", state.제목);
            params.append("userId", state.작성자);
            params.append("content", state.내용);

            const res = await axios.post(
                'https://kimdohui.com/admin/updateActionReact.jsp',
                params,
                {
                    headers: {
                        'Content-Type': 'application/x-www-form-urlencoded'
                    }
                }
            );

            if (res.status === 200 && Number(res.data) !== -1) {
                alert('수정되었습니다.');
                window.location.hash = '#/notice';
            } else {
                alert('수정할 수 없습니다');
            }

        } catch (err) {
            console.log('AXIOS 실패 ' + err);
        }
    }


    // 목록 버튼 클릭
    const onClickNoticeList = (e) => {
        e.preventDefault();
        window.location.hash = '#/notice';
    }

    return (
        <div id='noticeUpdate' className='noticeWrite'>
            <div className="container">
                <div className="left">
                    <NoticeLeftNavComponent />
                </div>
                <div className="right">
                    <div className="title">
                        <h2>공지사항 수정</h2>
                    </div>
                    <div className="content">
                        <form>
                            <ul>
                                <li>
                                    <label htmlFor="subject">제목<i>*</i></label>
                                    <input
                                        type="text"
                                        id="subject"
                                        name="subject"
                                        value={state.제목}
                                        onChange={onChangeSubject}
                                        placeholder='제목을 입력해주세요'
                                    />
                                </li>
                                <li>
                                    <label htmlFor="writer">작성자<i>*</i></label>
                                    <input
                                        type="text"
                                        id="writer"
                                        name="writer"
                                        value={state.작성자}
                                        onChange={onChangeWriter}
                                        placeholder='작성자를 입력해주세요'
                                        disabled
                                    />
                                </li>
                                <li>
                                    <label htmlFor="contents">내용<i>*</i></label>
                                    <textarea
                                        id="contents"
                                        name="contents"
                                        value={state.내용}
                                        onChange={onChangeContents}
                                        placeholder='내용을 입력해주세요'
                                    ></textarea>
                                </li>
                            </ul>

                            <div className="button-box update">
                                <button onClick={onClickSave}>저장</button>
                                <button onClick={onClickNoticeList}>목록</button>
                            </div>
                        </form>
                    </div>
                </div>
            </div>
        </div>
    );
}
