import React from 'react';
import goTop from './img/go_top/go_top.png';
import './scss/go_top.scss';
import $ from 'jquery';

export default function GoTopComponent() {

    React.useEffect(()=>{
        let sec4Top = 0;
        let goTop =  $('#goTop');
        let gotopBtn =  $('.gotop-btn');      
  
        try{
            sec4Top = $('#section4').offset().top;
        }
        catch(e) {
            sec4Top = 600;
        }        


        // 스크롤 이벤트 (네임스페이스)
        $(window).on('scroll.goTop', function () {
            if ($(window).scrollTop() >= sec4Top) {
                goTop.css({ bottom: '25px' });
            } else {
                goTop.css({ bottom: '-100px' });
            }
        });

        // Smooth Scroll (중복 애니메이션 방지)
        gotopBtn.on('click.goTop', function () {
            $('html, body')
                .stop(true, false)
                .animate({ scrollTop: 0 }, 60);
        });

        // cleanup
        return () => {
            $(window).off('.goTop');
            gotopBtn.off('.goTop');
        };
        // 스크롤이벤트
        // $(window).scroll(function(){
        //     if($(window).scrollTop() >= sec4Top){
        //         goTop.stop().css({bottom: '25px'});
        //     }
        //     else{
        //         goTop.stop().css({bottom: '-100px'});
        //     }
        // });

        // $(window).scroll(function(){
        //     if($(window).scrollTop() >= sec4Top){
        //         goTop.addClass('show');
        //     }
        //     else{
        //         goTop.removeClass('show');
        //     }
        // });

        // Smooth Scrolling
        // gotopBtn.on({
        //     click(){
        //         $('html, body').stop().animate({scrollTop: 0 }, 600);
        //     }
        // });

    },[]);

    return (
        <div id='goTop'>
            <button className='gotop-btn'>
                <img src={goTop} alt="" />    
            </button>    
        </div>
    );
};