import React from 'react';
import { Link } from 'react-router-dom';
import '../notice_scss/notice_left.scss';

export default function NoticeLeftNavComponent() {

    const onClickNoEvent=(e)=>{
        e.preventDefault();
    }

    return (
        <div id='noticeLeft'>
            <div className="container">
                <div className="title">
                    <h2>고객센터</h2>
                </div>
                <nav className='nav'>
                    <ul>
                        <li><Link to="/notice" className='on'>공지사항</Link></li>
                        <li onClick={onClickNoEvent}><a href="!#">자주하는질문</a></li>
                        <li onClick={onClickNoEvent}><a href="!#">1:1문의</a></li>
                        <li onClick={onClickNoEvent}><a href="!#">대량주문문의</a></li>
                    </ul>
                </nav>
                <div className="bottom" onClick={onClickNoEvent}>
                    <a href="!#">
                        <span>도움이 필요하신가요?</span>
                        <em>1:1문의하기</em>
                    </a>
                </div>
            </div>
        </div>
    );
};