import React from 'react';
import axios from 'axios';
import Linkify from 'react-linkify';
import { useNavigate, useLocation } from 'react-router-dom';
import { ConfirmContext } from '../../../context/ConfirmContext';
import { GlobalContext } from '../../../context/GlobalContext';
import './notice_scss/notice_view.scss';

export default function NoticeViewPageComponent() {

    const location = useLocation();
    const 번호 = location.state?.번호; // NoticeRightList에서 전달된 번호

    const { confirmModalOpen, ConfirmModalOkCancelOpen, isConfirmModalOkCancelResult, ConfirmModalOkCancelClose } = React.useContext(ConfirmContext);
    const { isAdmin } = React.useContext(GlobalContext);
    const navigate = useNavigate();

    const [bbsData, setBbsData] = React.useState({
        제목: '',
        내용: '',
        작성자: '',
        작성일: '',
        조회수: 0
    });

    // 글 조회 + 조회수 증가
    React.useEffect(() => {
        const params = new URLSearchParams();
        params.append('bbsId', 번호);

        axios.post('https://kimdohui.com/admin/viewActionReact.jsp', params, {
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' }
        })
        .then(res => {
            if (res.data.result === 1) {
                setBbsData({
                    제목: res.data.subject,
                    내용: res.data.content,
                    작성자: res.data.userId,
                    작성일: res.data.writeDate,
                    조회수: res.data.hit
                });
            } else {
                alert('글을 불러올 수 없습니다.');
                navigate('/notice');
            }
        })
        .catch(err => console.log('AXIOS 실패', err));
    }, [번호, navigate]);

    // 글 수정
    const onClickUpdate = e => {
        e.preventDefault();
        navigate('/notice_update', { state: { 번호, 제목: bbsData.제목, 작성자: bbsData.작성자, 내용: bbsData.내용 } });
    };

    // 글 삭제
    React.useEffect(() => {
        if (isConfirmModalOkCancelResult === '확인') {
            // axios 보내기 전에 번호 체크
            if (!번호) {
                confirmModalOpen('삭제할 글이 없습니다');
                ConfirmModalOkCancelClose('');
                return;
            }

            const params = new URLSearchParams();
            params.append('bbsId', 번호);

            axios.post('https://kimdohui.com/admin/deleteActionReact.jsp', params, {
                headers: { 'Content-Type': 'application/x-www-form-urlencoded' }
            })
            .then(res => {
                if (res.data.result === 1) {
                    confirmModalOpen('삭제되었습니다');
                    navigate('/notice');
                } 
                else {
                    confirmModalOpen('삭제 실패: ' + res.data.msg);
                }
            })
            .catch(err => console.log('AXIOS 실패', err))
            .finally(() => ConfirmModalOkCancelClose(''));
        } else if (isConfirmModalOkCancelResult === '취소') {
            ConfirmModalOkCancelClose('');
        }
    }, [isConfirmModalOkCancelResult, 번호, confirmModalOpen, navigate, ConfirmModalOkCancelClose]);

    const onClickDelete = e => {
        e.preventDefault();
        ConfirmModalOkCancelOpen('삭제하시겠습니까?');
    };

    const onClickNoticeList = e => {
        e.preventDefault();
        navigate('/notice');
    };

    return (
        <div id='noticeView'>
            <div className="container">
                <div className="title">
                    <h2>공지사항</h2>
                    <p>컬리의 새로운 소식들과 유용한 정보들을 한곳에서 확인하세요.</p>
                </div>
                <div className="content">
                    <ul>
                        <li><div className="left">조회수</div><div className="right">{bbsData.조회수}</div></li>
                        <li><div className="left">제목</div><div className="right">{bbsData.제목}</div></li>
                        <li><div className="left">작성자</div><div className="right">{bbsData.작성자}</div></li>
                        <li><div className="left">작성일</div><div className="right">{bbsData.작성일}</div></li>
                        <li><div className="contents">
                            <Linkify componentDecorator={(decoratedHref, decoratedText, key) => ( <a target='_blank' rel="noopener noreferrer" href={decoratedHref} key={key}>{decoratedText}</a>)}>
                            {bbsData.내용}</Linkify></div></li>
                    </ul>
                    <div className="button-box">
                        {isAdmin.adminId?
                        (<div className="left">
                            <button onClick={onClickUpdate}>수정</button>
                            <button onClick={onClickDelete}>삭제</button>
                        </div>)
                        :
                        (<div className="left"></div>)}
                        <div className="right">
                            <button onClick={onClickNoticeList}>목록</button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}
