import React from 'react';
import {Link} from 'react-router-dom';

export default function Sub4ComponentChild ({특가혜택}) {
    return (
        <ul>
           {
                특가혜택.map((item, idx)=>{
                    return(
                        <li key={idx}>
                            <Link to="!#">
                                <div className="img-box">
                                    <img src={`${process.env.PUBLIC_URL}/images/sub4/${item.이미지}`} alt="" />                                   
                                </div>                                
                            </Link>
                        </li> 
                    )
                })
           }
        </ul>
    );
};
